import { cloneValue } from './clone-value.mjs';

export const DELETE = Symbol('delete');

function isRecord(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    Object.prototype.toString.call(value) === '[object Object]'
  );
}

function assertMergeValue(value) {
  if (value === undefined || value === DELETE) return;
  if (value === null || typeof value === 'boolean' || typeof value === 'string') return;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError('invalid layer');
    return;
  }
  if (typeof value === 'function' || typeof value === 'symbol') {
    throw new TypeError('invalid layer');
  }
  if (Array.isArray(value)) {
    for (const item of value) assertMergeValue(item);
    return;
  }
  if (isRecord(value)) {
    for (const key of Object.keys(value)) {
      const prop = value[key];
      if (prop === undefined) continue;
      if (prop === DELETE) continue;
      assertMergeValue(prop);
    }
    return;
  }
  throw new TypeError('invalid layer');
}

function assertLayer(layer) {
  if (layer === undefined) return;
  if (!isRecord(layer)) throw new TypeError('invalid layer');
  for (const key of Object.keys(layer)) {
    const prop = layer[key];
    if (prop === undefined) continue;
    if (prop === DELETE) continue;
    assertMergeValue(prop);
  }
}

function mergeRecordInto(target, source) {
  for (const key of Object.keys(source)) {
    const incoming = source[key];
    if (incoming === undefined) continue;
    if (incoming === DELETE) {
      delete target[key];
      continue;
    }
    const previous = target[key];
    if (isRecord(previous) && isRecord(incoming)) {
      mergeRecordInto(previous, incoming);
    } else {
      target[key] = cloneValue(incoming);
    }
  }
}

export function mergeLayers(...layers) {
  const out = {};
  for (const layer of layers) {
    if (layer === undefined) continue;
    if (!isRecord(layer)) throw new TypeError('invalid layer');
    assertLayer(layer);
    mergeRecordInto(out, layer);
  }
  return cloneValue(out);
}

